xpath.script:
(function() {
    const form = document.querySelector('form[action*="/shop/address"], #address_form');
    if (!form) return;
    let hidden = form.querySelector('input[name="warehouse_selection"]');
    if (!hidden) {
        hidden = document.createElement('input');
        hidden.type = 'hidden';
        hidden.name = 'warehouse_selection';
        form.appendChild(hidden);
    }

    const cards = document.querySelectorAll('.o_wsale_preset_addresses [data-warehouse-card]');
    const buttons = document.querySelectorAll('.o_wsale_preset_addresses button[data-warehouse]');

    const selectWarehouse = (code) => {
        hidden.value = code;
        // persist immediately so it survives confirm without form re-save
        try {
            fetch('/shop/pickup/set', {
                method: 'POST',
                headers: {'Content-Type': 'application/json'},
                body: JSON.stringify({ warehouse: code }),
            }).catch(() => {});
        } catch (e) {}
        const nameInput = form.querySelector('input[name="name"]');
        const warehouseName = code === 'usa' ? 'USA Warehouse' : 'Panama Warehouse';
        if (nameInput) {
            const currentName = (nameInput.value || '').trim();
            if (!currentName || currentName === 'USA Warehouse' || currentName === 'Panama Warehouse' || currentName === 'Warehouse Pickup' || currentName === 'Public user') {
                nameInput.value = warehouseName;
            }
        }
        cards.forEach(card => {
            card.classList.toggle('is-selected', card.dataset.warehouseCard === code);
        });
        buttons.forEach(btn => {
            if (btn.dataset.warehouse === code) {
                btn.classList.remove('btn-outline-secondary');
                btn.classList.add('btn-success');
            } else {
                btn.classList.add('btn-outline-secondary');
                btn.classList.remove('btn-success');
            }
        });
    };

    buttons.forEach(btn => {
        btn.addEventListener('click', () => {
            selectWarehouse(btn.dataset.warehouse);
        });
    });
    // Preselect if value exists (from sale order), default to USA
    const initial = hidden.value || 'usa';
    selectWarehouse(initial);
})();


(function() {
    const pickupMeta = document.getElementById('pickup_meta');
    const pickupCode = pickupMeta ? pickupMeta.dataset.pickup : '';
    const pickupLabel = pickupCode === 'panama'
        ? 'Panama Warehouse'
        : pickupCode === 'usa'
            ? 'USA Warehouse'
            : '';
    if (!pickupLabel) return;

    // Remove any previous note if present
    document.querySelectorAll('.o_note_warehouse').forEach(el => el.remove());

    // Inject badge inside each delivery address card
    const cards = document.querySelectorAll('#delivery_address_list [name="address_card"] .card-body');
    const flag = pickupCode === 'panama' ? '🇵🇦' : '🇺🇸';
    cards.forEach(body => {
        if (body.querySelector('.pickup-badge')) return;
        const badge = document.createElement('div');
        badge.className = 'pickup-badge mb-1';
        badge.innerHTML = `<span>${flag}</span><span>${pickupLabel}</span>`;
        body.insertBefore(badge, body.firstChild);
    });
})();
